def calculate(s):
    s = s.replace(' ', '')
    nums = []
    ops = []

    def apply_top():
        b, a, op = nums.pop(), nums.pop(), ops.pop()                       # apply the MOST RECENT pending operator to the last two numbers
        if op == '+':
            nums.append(a + b)
        elif op == '-':
            nums.append(a - b)
        elif op == '*':
            nums.append(a * b)
        else:
            nums.append(int(a / b))

    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            nums.append(int(s[i:j]))
            i = j
        else:
            while ops and precedence(ops[-1]) >= precedence(s[i]):         # resolve any pending operator of >= precedence FIRST
                apply_top()
            ops.append(s[i])
            i += 1
    while ops:
        apply_top()
    return nums[0]

def precedence(op):
    return 2 if op in '*/' else 1


if __name__ == "__main__":
    print(calculate("3+5/2"))

