import java.util.*;

public class Main {
    int precedence(char op) {
        return (op == '*' || op == '/') ? 2 : 1;
    }

    int calculate(String s) {
        s = s.replace(" ", "");
        Deque<Integer> nums = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                int j = i;
                while (j < s.length() && Character.isDigit(s.charAt(j))) j++;
                nums.push(Integer.parseInt(s.substring(i, j)));
                i = j;
            } else {
                while (!ops.isEmpty() && precedence(ops.peek()) >= precedence(c)) {         // resolve any pending operator of >= precedence FIRST
                    applyTop(nums, ops);
                }
                ops.push(c);
                i++;
            }
        }
        while (!ops.isEmpty()) applyTop(nums, ops);
        return nums.pop();
    }

    void applyTop(Deque<Integer> nums, Deque<Character> ops) {
        int b = nums.pop(), a = nums.pop();
        char op = ops.pop();                                                                   // apply the MOST RECENT pending operator to the last two numbers
        if (op == '+') nums.push(a + b);
        else if (op == '-') nums.push(a - b);
        else if (op == '*') nums.push(a * b);
        else nums.push(a / b);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.calculate("3+5/2"));
    }
}

