    else if (op == '-') nums.push_back(a - b);
    else if (op == '*') nums.push_back(a * b);
    else nums.push_back(a / b);
}

int calculate(string s) {
    s.erase(remove(s.begin(), s.end(), ' '), s.end());
    vector<int> nums;
    vector<char> ops;
    int i = 0;
    while (i < (int)s.size()) {
        if (isdigit(s[i])) {
            int j = i;
            while (j < (int)s.size() && isdigit(s[j])) j++;
            nums.push_back(stoi(s.substr(i, j - i)));
            i = j;
        } else {
            while (!ops.empty() && precedence(ops.back()) >= precedence(s[i])) {                 // resolve any pending operator of >= precedence FIRST
                applyTop(nums, ops);
            }
            ops.push_back(s[i]);
            i++;
        }
    }
    while (!ops.empty()) applyTop(nums, ops);
    return nums.back();
}

