import java.util.*;

public class Main {
    int calculate(String s) {
        Deque<Integer> stack = new ArrayDeque<>();                                    // holds SIGNED terms, already fully resolved for * and /
        int num = 0;
        char op = '+';                                                                  // the operator that PRECEDED the number currently being built
        s = s.replace(" ", "") + "+";                                                   // a trailing '+' forces the final number to be flushed too
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            } else {
                if (op == '+') stack.push(num);
                else if (op == '-') stack.push(-num);
                else if (op == '*') stack.push(stack.pop() * num);                          // resolve immediately: no operator has higher precedence to wait for
                else stack.push(stack.pop() / num);                                            // truncate toward zero (Java's integer division already does this)
                op = c;
                num = 0;
            }
        }
        int total = 0;
        for (int v : stack) total += v;
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.calculate("3+5/2"));
    }
}

